    for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
        if 0<=rr<H and 0<=cc<W and (rr,cc) not in wall and (rr,cc) not in comp:
            comp.add((rr,cc));q.append((rr,cc))
