D={}
q=deque()
for r,c in comp:
    if any(not(0<=rr<H and 0<=cc<W) or (rr,cc) not in comp for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):
        D[(r,c)]=0;q.append((r,c))
while q:
    r,c=q.popleft()
    for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
        if (rr,cc) in comp and (rr,cc) not in D:
            D[(rr,cc)]=D[(r,c)]+1;q.append((rr,cc))
cand6=[[3]*W for _ in range(H)]
for (r,c),d in D.items(): cand6[r][c]=[7,4][d%2]
rings(cand6,0,19,12,19,[6,7])
for r in range(5,10):
    for c in range(4,11): cand6[r][c]=2
for r,c in wall: cand6[r][c]=9
